/// Returns an order if there is currently an order that is being filled
///
/// If there are multiple orders in `Filling` state we assume that the oldest one is the one to
/// continue processing and mark all other orders as `Failed` with `TimedOut` as the failure reason.
pub fn maybe_get_order_in_filling() -> Result<Option<trade::order::Order>> {
    let mut db = connection()?;
    let orders = Order::get_by_state(OrderState::Filling, &mut db)?;

    if orders.is_empty() {
        return Ok(None);
    }

    // There can be multiple orders in `Filling` state if the app crashed at an unfortunate point
    // in time. In that case we continue with the oldest order and fail all the others.
    let mut orders = orders;
    orders.sort_by_key(|order| order.creation_timestamp);

    let oldest_order = orders
        .first()
        .expect("at this point we know there is at least one order in `Filling` state")
        .clone();

    if orders.len() > 1 {
        tracing::warn!(
            oldest_order = %oldest_order.id,
            num_orders_in_filling = orders.len(),
            "Multiple orders are being filled at the same time, continuing with the oldest one and failing the others"
        );

        for order in orders.into_iter().skip(1) {
            tracing::debug!(
                order_id = %order.id,
                "Failing order in `Filling` state since there are multiple orders being filled"
            );

            Order::update_state(
                order.id.clone(),
                (OrderState::Failed, None, Some(FailureReason::TimedOut)),
                &mut db,
            )
            .context("Failed to mark order in `Filling` state as failed")?;

